import test from 'node:test'
import assert from 'node:assert'
const wait = ms => new Promise(r => setTimeout(r, ms))
test('integration (slow on purpose: about 13 min)', async t => {
  for (let i = 1; i <= 26; i++) {
    await t.test('scenario ' + i, async () => { await wait(30000); assert.ok(true) })
  }
})

